package com.hrms.booking;
import com.hrms.shared.*;import com.hrms.inventory.*;import com.hrms.promotion.CouponService;import com.hrms.messaging.Events;
import java.util.*;import java.time.*;import java.math.BigDecimal;import org.springframework.stereotype.Service;import org.springframework.dao.DuplicateKeyException;import org.springframework.beans.factory.annotation.Value;
@Service public class BookingService {
 private final Db db;private final Tx tx;private final InventoryService inventory;private final CouponService coupons;private final Events events;private final int ttl;
 public BookingService(Db db,Tx tx,InventoryService inventory,CouponService coupons,Events events,@Value("${hrms.booking-ttl-seconds}") int ttl){this.db=db;this.tx=tx;this.inventory=inventory;this.coupons=coupons;this.events=events;this.ttl=ttl;}
 public static LocalDate date(Object d){return d instanceof java.sql.Date x?x.toLocalDate():LocalDate.parse(d.toString().substring(0,10));}
 public Map<String,Object> get(long id){return Problem.found(db.one("SELECT * FROM bookings WHERE id=?",id));}
 public Map<String,Object> create(long user,String request,String quote,Long coupon){String fingerprint=quote+":"+coupon;var old=db.one("SELECT * FROM bookings WHERE user_id=? AND client_request_id=?",user,request);if(old!=null)return replay(old,fingerprint);
 try{return tx.run(()->{var q=Problem.found(db.one("SELECT *,expires_at>UTC_TIMESTAMP(6) AS valid FROM quotes WHERE id=? FOR UPDATE",quote));var replay=db.one("SELECT * FROM bookings WHERE user_id=? AND client_request_id=?",user,request);if(replay!=null)return replay(replay,fingerprint);Problem.require(Db.id(q,"user_id")==user,403,"QUOTE_FORBIDDEN");Problem.require(Db.number(q,"valid")==1,409,"QUOTE_EXPIRED");long room=Db.id(q,"room_type_id");var rt=room(room);LocalDate in=date(q.get("check_in"));Problem.require(!in.isBefore(LocalDate.now(ZoneId.of((String)rt.get("timezone")))),409,"STAY_IN_PAST");BigDecimal subtotal=Db.money(q,"total");BigDecimal discount=coupons.reserve(coupon,user,Db.id(rt,"hotel_id"),subtotal);
 long id=insert(user,request,fingerprint,quote,rt,in,date(q.get("check_out")),Db.number(q,"quantity"),subtotal,discount,coupon,null);
 for(var n:db.list("SELECT * FROM quote_nights WHERE quote_id=? ORDER BY stay_date",quote))inventory.hold(id,room,date(n.get("stay_date")),Db.number(q,"quantity"),Db.money(n,"price"));coupons.attach(coupon,id);events.add("BOOKING_CREATED",id);return get(id);});}
 catch(DuplicateKeyException e){old=db.one("SELECT * FROM bookings WHERE user_id=? AND client_request_id=?",user,request);if(old!=null)return replay(old,fingerprint);throw e;}
 }
 private Map<String,Object> replay(Map<String,Object> b,String fingerprint){Problem.require(b.get("request_fingerprint").equals(fingerprint),409,"IDEMPOTENCY_CONFLICT");return b;}
 public Map<String,Object> room(long room){return Problem.found(db.one("SELECT r.*,h.timezone FROM room_types r JOIN hotels h ON h.id=r.hotel_id WHERE r.id=? AND r.status='ACTIVE' AND h.status='OPEN'",room));}
 private long insert(long user,String request,String fingerprint,String quote,Map<String,Object> room,LocalDate in,LocalDate out,int qty,BigDecimal subtotal,BigDecimal discount,Long coupon,Long campaign){return db.insert("INSERT INTO bookings(user_id,client_request_id,request_fingerprint,quote_id,hotel_id,room_type_id,check_in,check_out,quantity,subtotal,discount,total,status,expires_at,coupon_id,campaign_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'PENDING_PAYMENT',DATE_ADD(UTC_TIMESTAMP(6),INTERVAL ? SECOND),?,?)",user,request,fingerprint,quote,Db.id(room,"hotel_id"),Db.id(room,"id"),in,out,qty,subtotal,discount,subtotal.subtract(discount),ttl,coupon,campaign);}
 /** Must be invoked inside the seckill consumer transaction after locking request and campaign. */
 public Map<String,Object> createSeckill(long user,String request,Map<String,Object> campaign){var rt=room(Db.id(campaign,"room_type_id"));var in=date(campaign.get("check_in"));var out=date(campaign.get("check_out"));var nights=CalendarController.nights(in,out);Problem.require(!in.isBefore(LocalDate.now(ZoneId.of((String)rt.get("timezone")))),409,"STAY_IN_PAST");var price=Db.money(campaign,"price");long id=insert(user,"seckill:"+request,"seckill:"+request,null,rt,in,out,1,price.multiply(BigDecimal.valueOf(nights.size())),BigDecimal.ZERO,null,Db.id(campaign,"id"));for(var d:nights)inventory.hold(id,Db.id(rt,"id"),d,1,price);events.add("BOOKING_CREATED",id);return get(id);}
 public Map<String,Object> locked(long id){return Problem.found(db.one("SELECT *,expires_at<=UTC_TIMESTAMP(6) AS expired FROM bookings WHERE id=? FOR UPDATE",id));}
 public void state(Map<String,Object> b,String target,String operation){long id=Db.id(b,"id");String old=(String)b.get("status");Problem.require(db.exec("UPDATE bookings SET status=? WHERE id=? AND status=?",target,id,old)==1,409,"INVALID_STATE");if(operation!=null)inventory.transition(id,operation);db.exec("INSERT INTO audit_logs(action,entity_ref) VALUES('ORDER_STATE',?)",id+":"+old+"->"+target);events.add("BOOKING_"+target,id);}
 public boolean due(Map<String,Object> b){return Db.number(b,"expired")==1;}
 public void expireLocked(Map<String,Object> b){if(b.get("status").equals("PENDING_PAYMENT")&&due(b)){state(b,"EXPIRED","RELEASE_HELD");coupons.release(Db.id(b,"id"));}}
 public Map<String,Object> expire(long id){return tx.run(()->{var b=locked(id);expireLocked(b);return get(id);});}
 public Map<String,Object> cancel(long id){return tx.run(()->{var b=locked(id);String state=(String)b.get("status");if(Set.of("CANCELLED","EXPIRED").contains(state))return b;
 if(state.equals("PENDING_PAYMENT")){state(b,"CANCELLED","RELEASE_HELD");coupons.release(id);}
 else {Problem.require(state.equals("CONFIRMED"),409,"INVALID_STATE");var h=db.one("SELECT timezone FROM hotels WHERE id=?",b.get("hotel_id"));Problem.require(date(b.get("check_in")).isAfter(LocalDate.now(ZoneId.of((String)h.get("timezone")))),409,"CANCELLATION_WINDOW_CLOSED");state(b,"CANCELLED","RELEASE_SOLD");refund(id);}
 return get(id);});}
 public void refund(long id){for(var payment:db.list("SELECT * FROM payments WHERE booking_id=? AND status='SUCCEEDED'",id)){db.exec("INSERT IGNORE INTO refunds(payment_id,booking_id,amount) VALUES(?,?,?)",payment.get("id"),id,payment.get("amount"));events.add("REFUND_REQUESTED",id);}}
 public Map<String,Object> checkIn(long id){return tx.run(()->{var b=locked(id);if(b.get("status").equals("CHECKED_IN"))return b;Problem.require(b.get("status").equals("CONFIRMED"),409,"INVALID_STATE");var h=db.one("SELECT timezone FROM hotels WHERE id=?",b.get("hotel_id"));var today=LocalDate.now(ZoneId.of((String)h.get("timezone")));Problem.require(!today.isBefore(date(b.get("check_in")))&&today.isBefore(date(b.get("check_out"))),409,"OUTSIDE_STAY");int qty=Db.number(b,"quantity");var rooms=db.list("SELECT id FROM physical_rooms WHERE room_type_id=? AND status='AVAILABLE' ORDER BY id LIMIT ? FOR UPDATE",b.get("room_type_id"),qty);Problem.require(rooms.size()==qty,409,"PHYSICAL_ROOM_UNAVAILABLE");for(var r:rooms){db.exec("UPDATE physical_rooms SET status='OCCUPIED' WHERE id=? AND status='AVAILABLE'",r.get("id"));db.exec("INSERT INTO booking_room_assignments(booking_id,room_id) VALUES(?,?)",id,r.get("id"));}state(b,"CHECKED_IN",null);return get(id);});}
 public Map<String,Object> checkOut(long id){return tx.run(()->{var b=locked(id);if(b.get("status").equals("CHECKED_OUT"))return b;Problem.require(b.get("status").equals("CHECKED_IN"),409,"INVALID_STATE");for(var room:db.list("SELECT room_id FROM booking_room_assignments WHERE booking_id=? ORDER BY room_id",id))Problem.require(db.exec("UPDATE physical_rooms SET status='CLEANING' WHERE id=? AND status='OCCUPIED'",room.get("room_id"))==1,409,"ROOM_STATE_INCONSISTENT");state(b,"CHECKED_OUT",null);return get(id);});}
}
